Sort by start, then merge whenever the next start is at or before the previous end, including touching endpoints. This implementation preserves the input and returns [] for empty input. Call solve(intervals) directly; time is O(n log n), and space is O(n).

```javascript
function solve(intervals) {
  const sorted = intervals.map(([start, end]) => [start, end]);
  sorted.sort((a, b) => a[0] - b[0]);

  const merged = [];
  for (const [start, end] of sorted) {
    const last = merged[merged.length - 1];
    if (last && start <= last[1]) {
      last[1] = Math.max(last[1], end);
    } else {
      merged.push([start, end]);
    }
  }
  return merged;
}
```

